import { bffDownload } from "@/api/bff";
import { saveFile } from "@/lib/download";

// Energy reports in Excel (P-52, D-92): generated by the BFF, for every role on the apartments they see. Monthly
// (month in the apartment's time zone) or for one stay; the amount in euro comes from the price per kWh set by the admin.

export type EnergyReport = { month: string } | { booking_id: string };

/** Downloads the report; the file name is the server's (consumi-<apartment>-<month or booking>.xlsx). */
export async function downloadEnergyReport(aptId: string, which: EnergyReport, correlationId: string): Promise<string> {
  const period = "month" in which ? which.month : which.booking_id;
  const { blob, name } = await bffDownload(`/app/apartments/${encodeURIComponent(aptId)}/energy/export`, {
    query: which,
    correlationId,
    fallbackName: `consumi-${aptId}-${period}.xlsx`,
  });
  saveFile(blob, name);
  return name;
}

/** The last `count` months in the time zone `tz`, newest first, as YYYY-MM (the current month included). */
export function recentMonths(tz: string, count = 12, now = new Date()): string[] {
  const parts = new Intl.DateTimeFormat("en-US", { timeZone: tz, year: "numeric", month: "2-digit" }).formatToParts(now);
  const year = Number(parts.find((p) => p.type === "year")?.value);
  const month = Number(parts.find((p) => p.type === "month")?.value);
  return Array.from({ length: count }, (_, i) => {
    const d = new Date(Date.UTC(year, month - 1 - i, 1));
    return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}`;
  });
}

/** "ottobre 2026" for "2026-10". */
export function monthLabel(month: string): string {
  const [y, m] = month.split("-").map(Number);
  return new Intl.DateTimeFormat("it-IT", { month: "long", year: "numeric", timeZone: "UTC" }).format(new Date(Date.UTC(y, m - 1, 1)));
}
